pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, address caller) public {
        vm.assume(depositAmount > 0 && depositAmount <= type(uint64).max);
        vm.assume(caller != address(0) && caller != address(c) && caller.code.length == 0);

        // Deposit funds into the contract from the caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        uint256 balBefore = address(c).balance;
        uint256 callerBalBefore = c.balances(caller);
        require(callerBalBefore > 0, "caller must have positive balance");

        uint256 gasBefore = gasleft();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(C.withdraw.selector));
        uint256 gasAfter = gasleft();
        uint256 gasUsed = gasBefore - gasAfter;

        // The invariant: after a successful withdraw, the contract's ETH balance must have decreased
        // by exactly the caller's pre-withdraw balance (the funds were actually transferred).
        // The mutant sends 0 ether, so after a successful withdraw the contract's balance will be unchanged,
        // while the correct contract sends the full balance.
        uint256 balAfter = address(c).balance;
        if (success) {
            assertTrue(balBefore > balAfter, "successful withdraw must reduce contract balance");
        }
    }
}

