pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);

        // Record initial total supply of ether in the contract
        uint256 totalBalancesBefore = sumAllBalances();
        uint256 initialContractBalance = address(c).balance;

        // First, deposit some ether into the contract on behalf of actor
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        // Record state after deposit
        uint256 totalBalancesAfterDeposit = sumAllBalances();
        uint256 contractBalanceAfterDeposit = address(c).balance;

        // The operator withdraws: any arbitrary call from any arbitrary actor
        // We use a fresh, empty address to avoid pre-existing balances
        vm.prank(actor);
        c.withdraw();

        // Record final state
        uint256 totalBalancesAfter = sumAllBalances();
        uint256 contractBalanceAfter = address(c).balance;

        // Invariant: total balances + contract balance remains constant across the withdraw.
        // Since balances are internal accounting and contract.balance holds the actual ether,
        // the sum should be preserved (no Ether destroyed/created outside the contract).
        // Specifically: (totalBalancesAfterDeposit + contractBalanceAfterDeposit) == (totalBalancesAfter + contractBalanceAfter)
        assertTrue(
            totalBalancesAfterDeposit + contractBalanceAfterDeposit == totalBalancesAfter + contractBalanceAfter
        );
    }

    // Helper to sum all balances. Since we cannot enumerate keys, we rely on the fact that only the actor has a balance.
    function sumAllBalances() internal view returns (uint256 sum) {
        // We know only the actor deposited, and balances are public.
        // However, other addresses might have zero balance. Since we cannot iterate,
        // we leverage that total Ether in the system = contract balance + sum of all balances.
        // But sum of all balances is not directly readable.
        // Instead, we can compute total Ether ever received minus total Ether ever sent out.
        // Since the contract is simple, we can use the fact that after deposit, the contract balance
        // equals total deposits (no withdrawals yet). After withdrawal, the contract balance equals
        // total deposits minus paid-out amounts. However, the invariant about totalBalances + contractBalance
        // being constant is equivalent to: the contract's ether balance increases by deposits and decreases
        // by withdrawals. Balances map entries sum to total deposits minus total withdrawals.
        // So sum(balances) + contractBalance = totalDeposits.
        // We cannot directly compute totalDeposits without storage.
        // Alternative: we can check that the balance of the actor corresponds to the paid amount.
        // But the bug pays to address(0) instead of actor, so actor's balance is zeroed but actor received nothing.
        // That breaks: after withdraw, actor balance == 0, but actor's ether balance hasn't increased by the previous balance.
        // We can check that actor's ether balance did not increase after the call, which should have happened.
        // Actually the invariant: For any address that withdraws, the ether sent equals the balance deducted.
        // We'll structure the test to check that the actor's ether balance change + their balance change sums to zero.
    }
}

