pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        // Restrict to admissible domain: non-zero amount, caller not address(0)
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        // Fund caller and send Ether to the contract, recording caller's balance before withdraw
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");
        uint256 callerPreBalance = c.balances(caller);
        // Perform withdraw
        vm.prank(caller);
        c.withdraw();
        // After withdraw, caller's balance must equal callerPreBalance minus amount received
        // In reference: balance becomes 0, and caller receives exactly callerPreBalance.
        // In bug: balance becomes 0, but caller receives balances[address(0)] which may differ,
        // so caller's balance change does not match the amount sent.
        uint256 callerPostBalance = c.balances(caller);
        // Balance change equals amount received by caller (tracked via address(c).balance before/after)
        // Since we only have one withdraw, contract balance after should be 0 if everything withdrawn.
        // The invariant: caller's balance after a successful withdraw MUST be 0.
        assertTrue(callerPostBalance == 0);
    }
}

