pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address other) public {
        vm.assume(other != address(0) && other != address(this) && other != address(c));
        vm.assume(depositAmount > 0 && withdrawAmount > 0 && withdrawAmount <= depositAmount);
        vm.deal(address(this), depositAmount);
        vm.prank(address(this));
        (bool s,) = address(c).call{value: depositAmount}("");
        require(s, "deposit to fail");
        // Record initial total balance
        uint256 initialTotal = depositAmount;

        // Deploy reentrant attacker
        Attacker attacker = new Attacker(c, withdrawAmount);
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        (bool attackerDepositSuccess,) = address(c).call{value: depositAmount}("");
        require(attackerDepositSuccess, "attacker deposit failed");

        vm.prank(address(attacker));
        attacker.attack();

        // Compute current total balances plus ether after attack
        uint256 total = address(c).balance;
        total += c.balances(address(this));
        total += c.balances(address(attacker));
        total += c.balances(other);
        assertTrue(total == initialTotal, "ether + total balances must equal initial ether");
    }
}

contract Attacker {
    C public target;
    uint256 public amount;
    bool public reentered;
    constructor(C _target, uint256 _amount) payable {
        target = _target;
        amount = _amount;
        reentered = false;
    }
    function attack() external {
        target.withdraw();
    }
    receive() external payable {
        if (!reentered && address(target).balance >= amount) {
            reentered = true;
            target.withdraw();
        }
    }
}

