pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Fund actor and deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok);

        // Perform first withdraw (should succeed in both versions)
        vm.prank(actor);
        c.withdraw();

        // The property: after the first withdraw completes, the contract's balance is zero
        // Because the correct version resets the lock and allows subsequent withdraws,
        // while the buggy version leaves the lock true, causing a revert on any subsequent withdraw.
        // If a second withdraw is attempted, the correct version processes it (balance stays 0),
        // but the buggy version reverts, leaving the balance unchanged from the first withdraw result.
        // However, after the first withdraw, balances[actor] is 0 in both, so we check contract balance.
        assertEq(address(c).balance, 0, "contract balance must be zero after single withdraw");
    }
}

